import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int a = Integer.parseInt(parts[0]);
        int b = Integer.parseInt(parts[1]);
        int l = Integer.parseInt(parts[2]);
        int r = Integer.parseInt(parts[3]);

        System.out.println(compute(a, b, l, r));
    }

    static int compute(int a, int b, int l, int r) {
        if ((r - l + 1) > 2 * (a + b))
            return (a <= b) ? a + 1 : (2 * a - b);

        int[] flag = new int[3 * (a + b) + 1];

        int temp = 0;
        for (int i = 1; i <= a; i++) {
            flag[i] = i;
            temp = i;
        }

        for (int i = a + 1; i <= a + b; i++) {
            flag[i] = temp;
        }

        for (int i = a + b + 1; i <= a + b + a; i++) {
            int tc = 1;
            while (contains(flag, tc, a + b - a + 1, i - 1))
                tc++;
            flag[i] = tc;
            temp = flag[i];
        }
        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            flag[i] = temp;
        }
        for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
            flag[i] = flag[i - (a + b)];
        }

        int[] flagc = new int[25];
        int templ = l % (a + b);
        if (templ == 0) templ += a + b;
        int tempr = r - l + templ;
        if (tempr < templ) tempr += a + b;
        for (int i = templ; i <= tempr; i++) {
            flagc[flag[i]] = 1;
        }

        int res = 0;
        for (int i = 1; i <= 24; i++)
            res += flagc[i];

        return res;
    }

    static boolean contains(int[] a, int b, int l, int r) {
        for (int i = l; i <= r; i++) {
            if (a[i] == b)
                return true;
        }
        return false;
    }
}
